-- =============================================================================
-- Geomacro national statistical office directory
--
-- Discovery source: U.S. Census Bureau "Related International Statistical
-- Activities", page revised June 5, 2026. Internal candidate inventory only.
-- No source is enabled for ingestion or commercial signals by this migration.
-- =============================================================================
begin;

create table if not exists public.live_country_statistics_source_directory (
 country_iso2 text primary key,
 office_name text not null,
 office_url text not null,
 discovery_source_url text not null default 'https://cdn.www.census.gov/programs-surveys/international-programs/about/related-sites.html',
 discovery_revised_at date not null default date '2026-06-05',
 verification_state text not null default 'DISCOVERED'
   check (verification_state in ('DISCOVERED','VERIFIED','REJECTED')),
 notes text not null default 'Candidate national statistical office source; certification remains pending.',
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);

