 notes=excluded.notes,updated_at=now();

insert into public.live_global_source_universe
(universe_id,scope_type,scope_code,source_role,source_id,priority,required,notes)
select
 'COUNTRY:' || r.iso3 || ':STATISTICS_OFFICE:' || 'stats_office_' || lower(d.country_iso2),
 'COUNTRY',r.iso3,'STATISTICS_OFFICE','stats_office_' || lower(d.country_iso2),
 7,true,'Direct national statistics office candidate for macro, fiscal, labour and production observations.'
from public.live_country_statistics_source_directory d
join public.live_country_registry r on upper(r.iso2)=upper(d.country_iso2)
where r.enabled=true
on conflict(scope_type,scope_code,source_role,source_id) do update set
 priority=excluded.priority,required=excluded.required,notes=excluded.notes,updated_at=now();

create or replace view public.live_country_statistics_source_directory_status
with (security_invoker=true)
as
select
 count(*)::bigint as directory_rows,
 count(*) filter (where verification_state='VERIFIED')::bigint as verified_rows,
 count(*) filter (where verification_state='DISCOVERED')::bigint as discovered_rows,
 194::bigint as expected_country_baseline,
 (count(*)=194) as directory_complete,
 false as certification_gate_open
from public.live_country_statistics_source_directory;

alter table public.live_country_statistics_source_directory enable row level security;
revoke all on public.live_country_statistics_source_directory from public,anon,authenticated;
grant select on public.live_country_statistics_source_directory to service_role;

comment on table public.live_country_statistics_source_directory is
 'Internal national statistical office directory derived from the U.S. Census Bureau international statistical office directory revised 2026-06-05. Direct reuse and machine access are separately certified.';

commit;
